const body = $json.body || $json;
const binary = $binary?.data;

const documentText = body.document_text || body.text || '';
const supplied = body.extraction || body.extraction_override || null;

const fileName = body.file_name || binary?.fileName || 'invoice-upload';
const mimeType = body.mime_type || binary?.mimeType || 'application/octet-stream';

const hashSource =
  body.document_hash ||
  `${fileName}|${documentText}|${JSON.stringify(supplied || '')}`;

let hash = 0;

for (let i = 0; i < hashSource.length; i++) {
  hash = ((hash << 5) - hash) + hashSource.charCodeAt(i) | 0;
}

return [
  {
    json: {
      source: $json.source || 'webhook',
      demo_case: body.demo_case || null,
      file_name: fileName,
      mime_type: mimeType,
      document_text: documentText,
      extraction_override: supplied,
      document_hash: body.document_hash || `local-${Math.abs(hash)}`,
      received_at: new Date().toISOString(),
      audit_events: [
        {
          event_type: 'DOCUMENT_RECEIVED',
          actor: 'finance-intake',
          details: {
            file_name: fileName,
            mime_type: mimeType
          }
        }
      ]
    },
    binary: $binary
  }
];

const data = $json;
const extraction = data.extraction_override;

const prompt = {
  model: 'llama3.1',
  stream: false,
  format: 'json',
  prompt: `You are a finance document extraction assistant.

Extract ONLY JSON with this exact schema:

invoice_number,
invoice_date,
due_date,
vendor_name,
vendor_tax_id,
currency,
subtotal,
tax,
total,
purchase_order_number,
line_items,
payment_terms,
bank_account,
confidence.

Do not make approval decisions.
If a field is unknown, use null.

Finance document text:
${data.document_text}`
};

return [
  {
    json: {
      ...data,
      ollama_request: prompt,
      extraction_override: extraction
    }
  }
];

const x = $json;
let extracted = x.extraction_override;
if (!extracted) {
  try {
    const raw = x.response || x.body?.response || x.data?.response || x.response?.body?.response;
    extracted = typeof raw === 'string' ? JSON.parse(raw) : raw;
  } catch (e) {}
}
if (!extracted || typeof extracted !== 'object') {
  return [{ json: { ...x, extraction_error: 'AI/OCR extraction unavailable or invalid JSON', action: 'exception', exception_reason: 'OCR_OR_AI_EXTRACTION_FAILURE', audit_events: [...(x.audit_events || []), { event_type: 'EXCEPTION_CREATED', actor: 'extraction-service', details: { reason: 'OCR_OR_AI_EXTRACTION_FAILURE' } }] } }];
}
return [{ json: { ...x, invoice: extracted, audit_events: [...(x.audit_events || []), { event_type: 'OCR_COMPLETED', actor: 'local-ocr-or-text-input', details: { text_available: !!x.document_text } }, { event_type: 'AI_EXTRACTION_COMPLETED', actor: 'local-ollama', details: { confidence: extracted.confidence ?? null } }] } }];

const p = $json.finance_payload;
const i = p.invoice || {};
const n = v => Number(v);
const subtotal = n(i.subtotal), tax = n(i.tax), total = n(i.total);
const tolerance = Number($env.FINANCE_ROUNDING_TOLERANCE || 2);
const pakistanTaxRate = Number($env.PAKISTAN_DEMO_TAX_RATE || 0.18);
const expectedTax = Number.isFinite(subtotal) ? +(subtotal * pakistanTaxRate).toFixed(2) : null;
const taxDifference = Number.isFinite(tax) && expectedTax !== null ? +Math.abs(tax - expectedTax).toFixed(2) : null;
const errors = [];
if (!i.invoice_number) errors.push('MISSING_INVOICE_NUMBER');
if (!i.invoice_date || Number.isNaN(Date.parse(i.invoice_date))) errors.push('INVALID_INVOICE_DATE');
if (!i.currency || !/^[A-Z]{3}$/.test(i.currency)) errors.push('INVALID_CURRENCY');
if (![subtotal, tax, total].every(Number.isFinite)) errors.push('NON_NUMERIC_FINANCIAL_FIELD');
if (Number.isFinite(subtotal) && Number.isFinite(tax) && Number.isFinite(total) && Math.abs((subtotal + tax) - total) > tolerance) errors.push('TOTAL_MISMATCH');
if (p.vendor_match_status !== 'matched') errors.push('UNKNOWN_VENDOR');
if (p.vendor?.status && p.vendor.status !== 'active') errors.push('INACTIVE_VENDOR');
if ($json.duplicate) errors.push('DUPLICATE_INVOICE');
if ($json.existing_payment_status === 'paid' || p.demo_case === 'already_paid') errors.push('ALREADY_PAID');
if (i.vendor_tax_id == null) errors.push('MISSING_TAX_ID');
if (taxDifference !== null && taxDifference > tolerance) errors.push('TAX_MISMATCH');
if (Number(i.confidence || 0) < 0.75) errors.push('LOW_AI_CONFIDENCE');
let action = 'auto_process';
let approval_status = 'not_required';
let status = 'validated';
if (errors.includes('DUPLICATE_INVOICE') || errors.includes('ALREADY_PAID')) { action = 'exception'; status = 'exception'; }
else if (errors.length) { action = 'human_review'; approval_status = 'pending'; status = 'review_required'; }
else if (total > 250000) { action = 'human_review'; approval_status = 'pending_finance'; status = 'approval_required'; }
else if (total > 50000) { action = 'human_review'; approval_status = 'pending_manager'; status = 'approval_required'; }
const decision = { action, status, approval_status, validation_status: errors.length ? 'failed' : 'passed', errors, tax: { expected_tax: expectedTax, provided_tax: tax, tax_difference: taxDifference, tolerance, configured_rate: pakistanTaxRate }, duplicate: !!$json.duplicate, existing_payment_status: $json.existing_payment_status, recommended_decision: action === 'auto_process' ? 'approve_and_post' : action === 'exception' ? 'reject_exception' : 'request_human_approval' };
return [{ json: { ...p, duplicate: !!$json.duplicate, existing_payment_status: $json.existing_payment_status, decision, audit_events: [...(p.audit_events || []), { event_type: 'DUPLICATE_CHECK_COMPLETED', actor: 'controlled-duplicate-lookup', details: { duplicate: !!$json.duplicate } }, { event_type: 'VALIDATION_COMPLETED', actor: 'deterministic-validation-engine', details: decision }] } }];

const p = $json.finance_payload;

return [
  {
    json: {
      ...p,
      invoice_id: $json.invoice_id,
      persisted_status: $json.status,
      audit_events: [
        ...(p.audit_events || []),
        {
          event_type:
            p.decision.action === 'auto_process'
              ? 'APPROVED'
              : p.decision.action === 'exception'
                ? 'EXCEPTION_CREATED'
                : 'APPROVAL_REQUIRED',
          actor: 'finance-operations-agent',
          details: {
            invoice_id: $json.invoice_id,
            decision: p.decision.action
          }
        }
      ]
    }
  }
];

const input = $json;
const base = input.finance_payload || input;
const accounting = input.accounting_transaction_id ? input : (input.body || {});
const posted = accounting.status === 'posted' || accounting.status === 'success';
return [{ json: { ...base, invoice_id: base.invoice_id || input.invoice_id, final_status: posted ? 'processed' : 'accounting_failed', accounting_transaction_id: accounting.accounting_transaction_id || null, payment_status: posted ? 'scheduled' : 'failed', audit_events: [...(base.audit_events || []), { event_type: posted ? 'ACCOUNTING_POSTED' : 'EXCEPTION_CREATED', actor: 'mock-accounting-api', details: { accounting_transaction_id: accounting.accounting_transaction_id || null, status: accounting.status || 'failed' } }, ...(posted ? [{ event_type: 'PAYMENT_CREATED', actor: 'finance-operations-agent', details: { status: 'scheduled' } }] : [])] } }];

