WITH p AS (SELECT $1::jsonb x), upd AS (
UPDATE invoices SET status=p.x->>'final_status', payment_status=p.x->>'payment_status', updated_at=now() FROM p WHERE id=(p.x->>'invoice_id')::uuid RETURNING invoices.id
), pay AS (
INSERT INTO payments (invoice_id,status,accounting_transaction_id,created_at,updated_at)
SELECT (p.x->>'invoice_id')::uuid,p.x->>'payment_status',p.x->>'accounting_transaction_id',now(),now() FROM p WHERE p.x->>'payment_status' IN ('scheduled','paid') ON CONFLICT (invoice_id) DO UPDATE SET status=EXCLUDED.status,accounting_transaction_id=EXCLUDED.accounting_transaction_id,updated_at=now()
) SELECT p.x AS finance_payload FROM p;

INSERT INTO audit_logs (invoice_id,event_type,actor,details,timestamp)
SELECT NULLIF($1::jsonb->>'invoice_id','')::uuid, event->>'event_type', event->>'actor', event->'details', now()
FROM jsonb_array_elements(COALESCE($1::jsonb->'audit_events','[]'::jsonb)) event;
SELECT $1::jsonb AS finance_payload;

