const b = $json.body || $json;
const decision = String(b.decision || '').toLowerCase();
if (!b.invoice_id || !['approve','reject'].includes(decision)) throw new Error('invoice_id and decision=approve|reject are required');
return [{ json: { invoice_id: b.invoice_id, approval_decision: decision, approver: b.approver || 'human-approver', reason: b.reason || null, audit_events: [{ event_type: decision === 'approve' ? 'APPROVED' : 'REJECTED', actor: b.approver || 'human-approver', details: { reason: b.reason || null } }] } }];

