WITH p AS (SELECT $1::jsonb x), upd AS (
UPDATE invoices SET approval_status=CASE WHEN p.x->>'approval_decision'='approve' THEN 'approved' ELSE 'rejected' END, status=CASE WHEN p.x->>'approval_decision'='approve' THEN 'approved_for_processing' ELSE 'rejected' END, updated_at=now() FROM p WHERE id=(p.x->>'invoice_id')::uuid RETURNING invoices.*
), app AS (
INSERT INTO approvals (invoice_id,decision,approver,reason,decided_at) SELECT (p.x->>'invoice_id')::uuid,p.x->>'approval_decision',p.x->>'approver',p.x->>'reason',now() FROM p
) SELECT upd.id AS invoice_id, upd.invoice_number, p.x AS finance_payload FROM upd,p;

