CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS vendors (vendor_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vendor_name text NOT NULL, tax_id text UNIQUE, email text, bank_account text, status text NOT NULL DEFAULT 'active', approval_limit numeric(14,2) DEFAULT 50000, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_number text NOT NULL, vendor_id uuid REFERENCES vendors(vendor_id), invoice_date date, due_date date, currency varchar(3), subtotal numeric(14,2), tax numeric(14,2), total numeric(14,2), purchase_order_number text, status text NOT NULL DEFAULT 'received', validation_status text, approval_status text, payment_status text NOT NULL DEFAULT 'pending', duplicate_flag boolean NOT NULL DEFAULT false, document_hash text UNIQUE, confidence numeric(5,4), raw_extraction jsonb, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS invoices_vendor_number_unique ON invoices(vendor_id, invoice_number) WHERE vendor_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS invoice_line_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES invoices(id) ON DELETE CASCADE, description text, quantity numeric(14,3), unit_price numeric(14,2), line_total numeric(14,2));
CREATE TABLE IF NOT EXISTS approvals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES invoices(id), decision text NOT NULL CHECK(decision IN ('approve','reject')), approver text NOT NULL, reason text, decided_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL UNIQUE REFERENCES invoices(id), status text NOT NULL CHECK(status IN ('pending','approved','scheduled','paid','failed')), accounting_transaction_id text, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id bigserial PRIMARY KEY, invoice_id uuid REFERENCES invoices(id), event_type text NOT NULL, actor text NOT NULL, details jsonb NOT NULL DEFAULT '{}'::jsonb, timestamp timestamptz NOT NULL DEFAULT now());

