ON CONFLICT (tax_id) DO UPDATE SET vendor_name=EXCLUDED.vendor_name,status=EXCLUDED.status,approval_limit=EXCLUDED.approval_limit;
SELECT 'Finance schema initialized and demo vendors seeded' AS result;
